using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
abstract class DesignSheetForm:Form {
 protected readonly TabControl Pages=new TabControl{Dock=DockStyle.Fill};protected readonly Dictionary<string,Control> Inputs=new Dictionary<string,Control>();protected bool Restoring;readonly string kind;readonly TextBox report=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",10)};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=40,Padding=new Padding(10)};
 protected DesignSheetForm(string title,string type){if(!AccessCodes.CanUseApp(type=="Purlin-Design"?ProgramAccess.PurlinDesign:ProgramAccess.TrussConnections))throw new Exception("Design Sheets access required.");kind=type;AppBrand.Apply(this);Text=title;ClientSize=new Size(1180,780);MinimumSize=new Size(820,600);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52,Padding=new Padding(8),AutoScroll=true};Action<string,Action> button=(text,action)=>{var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception ex){status.Text=ex.Message;status.ForeColor=Color.Firebrick;}};tools.Controls.Add(b);};button("Calculate",Calculate);button("Save sheet XML",Save);button("Open sheet XML",Open);button("Export report to Excel",ExportExcel);button("Print preview",()=>CalculationPreview.Show(this,BuildReport()));button("Export PDF",()=>{string text=BuildReport();using(var dialog=new SaveFileDialog{Filter="PDF|*.pdf",FileName=kind+".pdf"})if(dialog.ShowDialog(this)==DialogResult.OK)EstimatePdf.Write(dialog.FileName,text);});Controls.Add(Pages);Controls.Add(tools);Controls.Add(status);var output=new TabPage("Calculation report");output.Controls.Add(report);Pages.TabPages.Add(output);
 #if !ADMIN_APP
 var renewal=new AccessRenewal(this);FormClosed+=(s,e)=>renewal.Dispose();
 #endif
 }
 protected FlowLayoutPanel Section(string title,string note){var page=new TabPage(title);var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(18),WrapContents=true};page.Controls.Add(flow);if(!string.IsNullOrEmpty(note))flow.Controls.Add(new Label{Text=note,Width=1050,Height=76,Tag="FullWidth",ForeColor=PowTheme.Muted});flow.Resize+=(sender,args)=>{int width=Math.Max(280,flow.ClientSize.Width-flow.Padding.Horizontal-20);foreach(Control item in flow.Controls)if(Convert.ToString(item.Tag)=="FullWidth")item.Width=width;};var output=Pages.TabPages[Pages.TabPages.Count-1];Pages.TabPages.Remove(output);Pages.TabPages.Add(page);Pages.TabPages.Add(output);Pages.SelectedIndex=0;return flow;}
 protected TextBox NumberField(FlowLayoutPanel panel,string key,string label,string value){var text=new TextBox{Text=value,Width=280};Field(panel,key,label,text);return text;}
 protected ComboBox Choice(FlowLayoutPanel panel,string key,string label,string[] values){var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=280,DropDownWidth=500};combo.Items.AddRange(values);combo.AutoCompleteSource=AutoCompleteSource.ListItems;combo.AutoCompleteMode=AutoCompleteMode.SuggestAppend;if(values.Length>0)combo.SelectedIndex=0;Field(panel,key,label,combo);return combo;}
 protected CheckBox Toggle(FlowLayoutPanel panel,string key,string label,bool value){var check=new CheckBox{Text=label,Checked=value,Width=280,Height=40};Field(panel,key,"",check);return check;}
 protected void Field(FlowLayoutPanel panel,string key,string label,Control input){var box=new FlowLayoutPanel{Width=310,Height=94,FlowDirection=FlowDirection.TopDown,WrapContents=false};box.Controls.Add(new Label{Text=label,Width=280,Height=40});box.Controls.Add(input);panel.Controls.Add(box);Inputs.Add(key,input);}
 protected string Value(string key){return Inputs[key].Text.Trim();}protected double Number(string key){double value;if(!double.TryParse(Value(key),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new Exception("Check "+key+"; enter a finite number with a decimal point.");return value;}
 protected abstract string BuildReport();protected virtual void AfterRestore(){}
 public string CurrentReport(){return BuildReport();}
 void Calculate(){report.Text=BuildReport();status.ForeColor=PowTheme.Teal;status.Text="Calculated. Save sheet XML to keep inputs; exports contain the calculation report only.";Pages.SelectedIndex=Pages.TabCount-1;}
 void ExportExcel(){string text=BuildReport();using(var dialog=new SaveFileDialog{Filter="Excel workbook|*.xlsx",FileName=kind+"-Report.xlsx",OverwritePrompt=false})if(dialog.ShowDialog(this)==DialogResult.OK){using(var output=new ExcelLiveLink(dialog.FileName,true,false))output.UpdateDesignReport(kind,text);status.Text="Calculation report exported. Save sheet XML separately to retain editable inputs.";}}
 void Save(){using(var dialog=new SaveFileDialog{Filter="DTCE design sheet|*.design.xml",FileName=kind+".design.xml"})if(dialog.ShowDialog(this)==DialogResult.OK)File.WriteAllText(dialog.FileName,Snapshot());}
 void Open(){using(var dialog=new OpenFileDialog{Filter="DTCE design sheet|*.design.xml"})if(dialog.ShowDialog(this)==DialogResult.OK)Restore(File.ReadAllText(dialog.FileName));}
 internal string Snapshot(){var doc=new XmlDocument();var root=doc.CreateElement("DesignSheet");root.SetAttribute("type",kind);root.SetAttribute("version","1");doc.AppendChild(root);foreach(var pair in Inputs){var field=doc.CreateElement("Input");field.SetAttribute("key",pair.Key);field.InnerText=pair.Value is CheckBox?((CheckBox)pair.Value).Checked.ToString():pair.Value.Text;root.AppendChild(field);}return doc.OuterXml;}
 internal void Restore(string xml){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=2000000}))doc.Load(reader);if(doc.DocumentElement.Name!="DesignSheet"||doc.DocumentElement.GetAttribute("type")!=kind||doc.DocumentElement.GetAttribute("version")!="1")throw new Exception("Choose a matching design-sheet file.");var values=new Dictionary<string,string>();foreach(XmlElement element in doc.DocumentElement.SelectNodes("Input")){string key=element.GetAttribute("key");if(!Inputs.ContainsKey(key)||values.ContainsKey(key))throw new Exception("Invalid/duplicate design input.");values[key]=element.InnerText;}if(values.Count!=Inputs.Count)throw new Exception("Incomplete design sheet.");foreach(var pair in values){var combo=Inputs[pair.Key] as ComboBox;if(combo!=null&&!combo.Items.Contains(pair.Value))throw new Exception("Saved profile or selection is unavailable: "+pair.Key);if(Inputs[pair.Key] is CheckBox)bool.Parse(pair.Value);}Restoring=true;try{foreach(var pair in values){var check=Inputs[pair.Key] as CheckBox;if(check!=null)check.Checked=bool.Parse(pair.Value);else Inputs[pair.Key].Text=pair.Value;}}finally{Restoring=false;}AfterRestore();Calculate();}
}
class PurlinDesignForm:DesignSheetForm {
 readonly ComboBox profiles;readonly CheckBox verified;readonly TextBox ix,iy,ixy,sx,sy;
 public PurlinDesignForm():base("Purlin Design | Workbook ASD checks","Purlin-Design"){
  var geometry=Section("Geometry & loads","Based on PS Design of Purlin.xlsm. Signed wind normal to roof; negative values represent uplift/suction. This sheet evaluates the listed workbook flexure/deflection checks, not the complete cold-formed member design.");NumberField(geometry,"Name","Member / purlin name","Purlin");profiles=Choice(geometry,"Profile","Regan handbook purlin profile",SteelCatalog.Profiles.Where(p=>p.Kind=="Purlin").Select(p=>p.Name).ToArray());Choice(geometry,"Support","Support",new[]{"Simply supported","Cantilever"});NumberField(geometry,"Span","Span / cantilever length m","5");NumberField(geometry,"Spacing","Purlin spacing m","0.4");NumberField(geometry,"Angle","Roof angle deg","13");Choice(geometry,"SagRods","Effective sag rods",new[]{"0","1","2"});Choice(geometry,"Ceiling","Ceiling type",new[]{"Not supporting ceiling","Supporting nonplaster ceiling","Supporting plaster ceiling"});NumberField(geometry,"Dead","Superimposed dead load kPa","0.35");NumberField(geometry,"Live","Roof live load kPa","1");NumberField(geometry,"WindPressure","Signed pressure kPa","0");NumberField(geometry,"WindSuction","Signed suction kPa","0");NumberField(geometry,"Fy","Specified yield strength MPa","248");NumberField(geometry,"E","Modulus of elasticity MPa","200000");Toggle(geometry,"AlternateIncrease","Workbook alternate 4/3 allowable increase",true);
  var properties=Section("Section properties","Handbook PDF pp.43-44 supplies dimensions and mass only. Auto properties idealize nonoverlapping rectangular plates and neglect bend radii. For final use enter verified properties with the same geometric axes/centroid; nonzero Ixy must be retained for Z shapes. Additional buckling, shear and connection checks remain outside this sheet.");verified=Toggle(properties,"Verified","Use verified section properties",false);ix=NumberField(properties,"Ix","Ix mm4","1");iy=NumberField(properties,"Iy","Iy mm4","1");ixy=NumberField(properties,"Ixy","Ixy mm4 (signed)","0");sx=NumberField(properties,"Sx","Sx mm3","1");sy=NumberField(properties,"Sy","Sy mm3","1");profiles.SelectedIndexChanged+=(s,e)=>{if(!Restoring){verified.Checked=false;UpdateProperties();}};verified.CheckedChanged+=(s,e)=>{if(!Restoring)UpdateProperties();};UpdateProperties();
 }
 void UpdateProperties(){var p=PurlinProperties.Calculate(SteelCatalog.Find(profiles.Text));if(!verified.Checked){ix.Text=p.Ix.ToString("R",CultureInfo.InvariantCulture);iy.Text=p.Iy.ToString("R",CultureInfo.InvariantCulture);ixy.Text=p.Ixy.ToString("R",CultureInfo.InvariantCulture);sx.Text=p.Sx.ToString("R",CultureInfo.InvariantCulture);sy.Text=p.Sy.ToString("R",CultureInfo.InvariantCulture);}foreach(var text in new[]{ix,iy,ixy,sx,sy})text.ReadOnly=!verified.Checked;}
 protected override void AfterRestore(){UpdateProperties();}
 protected override string BuildReport(){var profile=SteelCatalog.Find(Value("Profile"));var p=PurlinProperties.Calculate(profile);if(verified.Checked){p.Ix=Number("Ix");p.Iy=Number("Iy");p.Ixy=Number("Ixy");p.Sx=Number("Sx");p.Sy=Number("Sy");p.Verified=true;}var input=new PurlinDesignInput{Name=Value("Name"),Profile=profile,Properties=p,Support=Value("Support"),Span=Number("Span"),Spacing=Number("Spacing"),Angle=Number("Angle"),SagRods=int.Parse(Value("SagRods")),Ceiling=Value("Ceiling"),Dead=Number("Dead"),Live=Number("Live"),WindPressure=Number("WindPressure"),WindSuction=Number("WindSuction"),Fy=Number("Fy"),E=Number("E"),AlternateIncrease=((CheckBox)Inputs["AlternateIncrease"]).Checked};return PurlinDesigner.Report(input,PurlinDesigner.Calculate(input));}
}
}
